def main():
    existing = get_existing_norms(exclude_slugs={"cv-alphabet-exp-n-z"})
    entries = []
    skipped = 0
    rank = 1

    for row in ITEMS:
        kind = row[0]
        headword = row[1]
        norm = norm_vocab(headword)
        if norm in existing:
            skipped += 1
            continue

        if kind == "noun":
            gender = row[2]
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            art = "El" if gender == "m" else "La"
            ex_es = f"{art} {headword} resulta muy común en el entorno cotidiano."
            ex_ar = f"يعد الـ{msa} شائعاً جداً في الحياة اليومية والبيئة المحيطة."
            entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "verb":
            paradigm = row[2]
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            ex_es = f"Solemos {headword} con bastante regularidad en nuestras actividades."
            ex_ar = f"نعتاد أن {msa} بانتظام كافٍ في أنشطتنا المختلفة."
            # Check if headword is a single infinitive or reflexive
            clean_hw = headword.strip()
            is_single_inf = " " not in clean_hw and (clean_hw.endswith(("ar", "er", "ir", "arse", "erse", "irse")))
            if is_single_inf:
                entry = make_verb(headword, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
            else:
                entry = make_expr(headword, "collocation", level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "adj":
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            ex_es = f"Este rasgo resulta muy {headword} en muchas situaciones reales."
            ex_ar = f"يبدو هذا الأمر {msa} جداً في مواقف واقعية كثيرة."
            entry = make_adj(headword, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        else:
            continue

        entries.append(entry)
        existing.add(norm)
        rank += 1

    print(f"Alphabet Expansion N-Z: Prepared {len(entries)} new entries (skipped {skipped} existing).")
    emit_bundle("vocab-cv-alphabet-exp-n-z.json", "cv-alphabet-exp-n-z", "معجم الحروف الإسبانية الموسع N إلى Z", entries)

if __name__ == "__main__":
    main()
